 shield:'<path d="M12 3 5 6v5.2c0 4.4 2.7 7.5 7 9.8 4.3-2.3 7-5.4 7-9.8V6l-7-3Z"/><path d="m9 12 2 2 4-4"/>',
 android:'<rect x="6" y="7" width="12" height="11" rx="3"/><path d="M8 7 6.5 4.8M16 7l1.5-2.2M4 10v5M20 10v5M9 18v3M15 18v3"/>',
